<?php
require_once __DIR__.'/DocumentService.php';
class TransferService
{
 private $db;public function __construct(PDO$db=null){$this->db=$db?:Database::getInstance()->connection();}
 public function create(array$data,array$user){$source=(int)$data['source_site_id'];$dest=(int)$data['destination_site_id'];if($source===$dest&&$data['transfer_type']!=='internal'){throw new RuntimeException('Les sites doivent être différents.');}Auth::requireSiteAccess($source);$this->db->beginTransaction();try{$number='TR-'.date('YmdHis').'-'.random_int(100,999);$s=$this->db->prepare("INSERT INTO stock_transfers(transfer_number,transfer_type,source_site_id,destination_site_id,requested_at,created_by,notes) VALUES(:number,:type,:source,:dest,NOW(),:user,:notes)");$s->execute(['number'=>$number,'type'=>$data['transfer_type'],'source'=>$source,'dest'=>$dest,'user'=>$user['id'],'notes'=>$data['notes']??null]);$id=$this->db->lastInsertId();foreach($data['items']as$item){$stock=$this->lockStock($item['finished_stock_id']);if(!$stock||(int)$stock['site_id']!==$source){throw new RuntimeException('Lot source invalide.');}$bags=(int)$item['quantity_bags'];$kg=(float)$stock['weight_kg']*$bags;if($bags<=0){throw new RuntimeException('Quantité invalide.');}$this->db->prepare('INSERT INTO stock_transfer_items(transfer_id,source_finished_stock_id,product_id,bag_format_id,requested_bags,requested_kg) VALUES(:transfer,:stock,:product,:format,:bags,:kg)')->execute(['transfer'=>$id,'stock'=>$stock['id'],'product'=>$stock['product_id'],'format'=>$stock['bag_format_id'],'bags'=>$bags,'kg'=>$kg]);}$this->history($id,null,'draft','create',$user);(new DocumentService($this->db))->register($data['transfer_type']==='internal'?'BTI':'BTR',$source,'stock_transfers',$id,'draft',date('Y-m-d H:i:s'),$user);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function submit($id,array$user){$this->simple($id,['draft'],'submitted','submit',$user);}
 public function approve($id,array$user){$this->db->beginTransaction();try{$t=$this->lockTransfer($id);$this->expect($t,['submitted']);if((int)$t['created_by']===(int)$user['id']&&!Auth::canSelfValidate($user['id'])){throw new RuntimeException('Le créateur ne peut pas valider.');}Auth::requireSiteAccess($t['source_site_id']);foreach($this->lockItems($id)as$item){$stock=$this->lockStock($item['source_finished_stock_id']);$bags=(int)$item['requested_bags'];$kg=(float)$item['requested_kg'];if((int)$stock['quantity_bags']-(int)$stock['reserved_bags']<$bags||(float)$stock['total_weight_kg']-(float)$stock['reserved_weight_kg']<$kg){throw new RuntimeException('Stock disponible insuffisant pour valider et réserver.');}$this->db->prepare('UPDATE finished_stocks SET reserved_bags=reserved_bags+:bags,reserved_weight_kg=reserved_weight_kg+:kg WHERE id=:id')->execute(['bags'=>$bags,'kg'=>$kg,'id'=>$stock['id']]);$this->db->prepare("INSERT INTO stock_transfer_reservations(transfer_item_id,quantity_bags,quantity_kg,created_by) VALUES(:item,:bags,:kg,:user)")->execute(['item'=>$item['id'],'bags'=>$bags,'kg'=>$kg,'user'=>$user['id']]);$reservationId=$this->db->lastInsertId();$this->db->prepare('UPDATE stock_transfer_items SET approved_bags=requested_bags,approved_kg=requested_kg,reserved_bags=requested_bags,reserved_kg=requested_kg WHERE id=:id')->execute(['id'=>$item['id']]);$this->movement($t,$item,$t['source_site_id'],'reserve',$bags,$kg,$stock['total_weight_kg'],$stock['total_weight_kg'],$stock['reserved_weight_kg'],$stock['reserved_weight_kg']+$kg,0,0,'reservation',$reservationId,$user);}$this->db->prepare("UPDATE stock_transfers SET status='reserved',approved_by=:user,approved_at=NOW() WHERE id=:id")->execute(['user'=>$user['id'],'id'=>$id]);$this->history($id,$t['status'],'reserved','approve_and_reserve',$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function reserve($id,array$user){$this->db->beginTransaction();try{$t=$this->lockTransfer($id);$this->expect($t,['approved']);foreach($this->lockItems($id)as$item){$stock=$this->lockStock($item['source_finished_stock_id']);$availableBags=(int)$stock['quantity_bags']-(int)$stock['reserved_bags'];$availableKg=(float)$stock['total_weight_kg']-(float)$stock['reserved_weight_kg'];if($availableBags<(int)$item['approved_bags']||$availableKg<(float)$item['approved_kg']){throw new RuntimeException('Stock disponible insuffisant pour réserver.');}$this->db->prepare('UPDATE finished_stocks SET reserved_bags=reserved_bags+:bags,reserved_weight_kg=reserved_weight_kg+:kg WHERE id=:id')->execute(['bags'=>$item['approved_bags'],'kg'=>$item['approved_kg'],'id'=>$stock['id']]);$this->db->prepare("INSERT INTO stock_transfer_reservations(transfer_item_id,quantity_bags,quantity_kg,created_by) VALUES(:item,:bags,:kg,:user)")->execute(['item'=>$item['id'],'bags'=>$item['approved_bags'],'kg'=>$item['approved_kg'],'user'=>$user['id']]);$this->db->prepare('UPDATE stock_transfer_items SET reserved_bags=approved_bags,reserved_kg=approved_kg WHERE id=:id')->execute(['id'=>$item['id']]);$this->movement($t,$item,$t['source_site_id'],'reserve',$item['approved_bags'],$item['approved_kg'],$stock['total_weight_kg'],$stock['total_weight_kg'],$stock['reserved_weight_kg'],$stock['reserved_weight_kg']+$item['approved_kg'],0,0,'reservation',$this->db->lastInsertId(),$user);}$this->setStatus($t,'reserved','reserve',$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function ship($id,array$quantities,array$user,$vehicle=null){$this->db->beginTransaction();try{$t=$this->lockTransfer($id);$this->expect($t,['reserved','partially_shipped']);$number='EXP-'.date('YmdHis').'-'.random_int(100,999);$this->db->prepare("INSERT INTO transfer_shipments(transfer_id,shipment_number,status,vehicle_reference,dispatched_at,created_by) VALUES(:transfer,:number,'dispatched',:vehicle,NOW(),:user)")->execute(['transfer'=>$id,'number'=>$number,'vehicle'=>$vehicle,'user'=>$user['id']]);$shipmentId=$this->db->lastInsertId();$total=0;foreach($this->lockItems($id)as$item){$bags=(int)($quantities[$item['id']]??0);if($bags<=0){continue;}$remaining=(int)$item['reserved_bags']-(int)$item['shipped_bags'];if($bags>$remaining){throw new RuntimeException('Expédition supérieure à la réservation.');}$stock=$this->lockStock($item['source_finished_stock_id']);$kg=(float)$stock['weight_kg']*$bags;if((int)$stock['quantity_bags']<$bags||(int)$stock['reserved_bags']<$bags){throw new RuntimeException('Stock physique ou réservé insuffisant.');}$pb=(float)$stock['total_weight_kg'];$rb=(float)$stock['reserved_weight_kg'];$tb=(float)$item['shipped_kg']-(float)$item['received_kg'];$this->db->prepare('UPDATE finished_stocks SET quantity_bags=quantity_bags-:bags,total_weight_kg=total_weight_kg-:kg,reserved_bags=reserved_bags-:bags_reserved,reserved_weight_kg=reserved_weight_kg-:kg_reserved WHERE id=:id')->execute(['bags'=>$bags,'kg'=>$kg,'bags_reserved'=>$bags,'kg_reserved'=>$kg,'id'=>$stock['id']]);$this->db->prepare('INSERT INTO transfer_shipment_items(shipment_id,transfer_item_id,quantity_bags,quantity_kg) VALUES(:shipment,:item,:bags,:kg)')->execute(['shipment'=>$shipmentId,'item'=>$item['id'],'bags'=>$bags,'kg'=>$kg]);$this->db->prepare('UPDATE stock_transfer_items SET shipped_bags=shipped_bags+:bags,shipped_kg=shipped_kg+:kg WHERE id=:id')->execute(['bags'=>$bags,'kg'=>$kg,'id'=>$item['id']]);$reservation=$this->row("SELECT * FROM stock_transfer_reservations WHERE transfer_item_id=? AND status='active' FOR UPDATE",[$item['id']]);if(!$reservation||$reservation['quantity_bags']<$bags){throw new RuntimeException('Réservation active incohérente.');}$left=(int)$reservation['quantity_bags']-$bags;$this->db->prepare("UPDATE stock_transfer_reservations SET quantity_bags=quantity_bags-:bags,quantity_kg=quantity_kg-:kg,status=:status,consumed_at=CASE WHEN :status_case='consumed' THEN NOW() ELSE consumed_at END WHERE id=:id")->execute(['bags'=>$bags,'kg'=>$kg,'status'=>$left===0?'consumed':'active','status_case'=>$left===0?'consumed':'active','id'=>$reservation['id']]);$this->movement($t,$item,$t['source_site_id'],'dispatch',$bags,$kg,$pb,$pb-$kg,$rb,$rb-$kg,$tb,$tb+$kg,'shipment',$shipmentId,$user);$total+=$bags;}if(!$total){throw new RuntimeException('Aucune quantité à expédier.');}$remaining=(int)$this->scalar('SELECT SUM(reserved_bags-shipped_bags) FROM stock_transfer_items WHERE transfer_id=?',[$id]);$this->setStatus($t,$remaining>0?'partially_shipped':'in_transit','ship',$user);(new DocumentService($this->db))->register('BS',$t['source_site_id'],'transfer_shipments',$shipmentId,'approved',date('Y-m-d H:i:s'),$user);$this->db->commit();return$shipmentId;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function receive($shipmentId,$key,array$lines,array$user,$notes=null){$this->db->beginTransaction();try{$existing=$this->row('SELECT * FROM transfer_receipts WHERE idempotency_key=? FOR UPDATE',[$key]);if($existing){$this->db->commit();return$existing['id'];}$shipment=$this->row('SELECT * FROM transfer_shipments WHERE id=? FOR UPDATE',[$shipmentId]);if(!$shipment||!in_array($shipment['status'],['dispatched','partially_received'],true)){throw new RuntimeException('Expédition non réceptionnable.');}$t=$this->lockTransfer($shipment['transfer_id']);Auth::requireSiteAccess($t['destination_site_id']);$receiptNumber='REC-'.date('YmdHis').'-'.random_int(100,999);$overall='accepted';$this->db->prepare("INSERT INTO transfer_receipts(transfer_id,shipment_id,receipt_number,idempotency_key,status,received_at,quality_notes,received_by) VALUES(:transfer,:shipment,:number,:key,'accepted',NOW(),:notes,:user)")->execute(['transfer'=>$t['id'],'shipment'=>$shipmentId,'number'=>$receiptNumber,'key'=>$key,'notes'=>$notes,'user'=>$user['id']]);$receiptId=$this->db->lastInsertId();foreach($this->shipmentItems($shipmentId)as$si){if(!isset($lines[$si['id']])){continue;}$accepted=(int)$lines[$si['id']]['accepted_bags'];$rejected=(int)$lines[$si['id']]['rejected_bags'];$received=$accepted+$rejected;$remaining=(int)$si['quantity_bags']-(int)$si['received_bags'];if($received<=0||$received>$remaining){throw new RuntimeException('Quantité réceptionnée invalide.');}$weight=(float)$si['quantity_kg']/(int)$si['quantity_bags'];$acceptedKg=$accepted*$weight;$rejectedKg=$rejected*$weight;$receivedKg=$acceptedKg+$rejectedKg;$quality=$rejected>0?($accepted>0?'non_conform':'rejected'):'conform';$this->db->prepare('INSERT INTO transfer_receipt_items(receipt_id,shipment_item_id,received_bags,received_kg,accepted_bags,accepted_kg,rejected_bags,rejected_kg,quality_status,quality_notes) VALUES(:receipt,:shipment_item,:received,:receivedkg,:accepted,:acceptedkg,:rejected,:rejectedkg,:quality,:notes)')->execute(['receipt'=>$receiptId,'shipment_item'=>$si['id'],'received'=>$received,'receivedkg'=>$receivedKg,'accepted'=>$accepted,'acceptedkg'=>$acceptedKg,'rejected'=>$rejected,'rejectedkg'=>$rejectedKg,'quality'=>$quality,'notes'=>$lines[$si['id']]['quality_notes']??null]);$receiptItemId=$this->db->lastInsertId();$item=$this->row('SELECT * FROM stock_transfer_items WHERE id=? FOR UPDATE',[$si['transfer_item_id']]);$transitBefore=(float)$item['shipped_kg']-(float)$item['received_kg'];$this->db->prepare('UPDATE transfer_shipment_items SET received_bags=received_bags+:bags,received_kg=received_kg+:kg WHERE id=:id')->execute(['bags'=>$received,'kg'=>$receivedKg,'id'=>$si['id']]);$this->db->prepare('UPDATE stock_transfer_items SET received_bags=received_bags+:received,received_kg=received_kg+:receivedkg,accepted_bags=accepted_bags+:accepted,accepted_kg=accepted_kg+:acceptedkg,rejected_bags=rejected_bags+:rejected,rejected_kg=rejected_kg+:rejectedkg WHERE id=:id')->execute(['received'=>$received,'receivedkg'=>$receivedKg,'accepted'=>$accepted,'acceptedkg'=>$acceptedKg,'rejected'=>$rejected,'rejectedkg'=>$rejectedKg,'id'=>$item['id']]);if($accepted>0){$dest=$this->destinationStock($t['destination_site_id'],$item,$user);$before=$dest['total_weight_kg'];$this->db->prepare("UPDATE finished_stocks SET quantity_bags=quantity_bags+:bags,total_weight_kg=total_weight_kg+:kg,status='active' WHERE id=:id")->execute(['bags'=>$accepted,'kg'=>$acceptedKg,'id'=>$dest['id']]);$this->movement($t,$item,$t['destination_site_id'],'receipt',$accepted,$acceptedKg,$before,$before+$acceptedKg,0,0,$transitBefore,$transitBefore-$receivedKg,'receipt',$receiptId,$user);}if($rejected>0||$received<$remaining){$overall=$accepted>0?'partially_accepted':'rejected';$this->nonConformity($t,$receiptId,$receiptItemId,$remaining,$received,$rejected,$user,$lines[$si['id']]['quality_notes']??'Écart de réception');}if($rejected>0){$this->createReturnLocked($t,$receiptId,$item,$rejected,$rejectedKg,$user);}}$this->db->prepare('UPDATE transfer_receipts SET status=:status WHERE id=:id')->execute(['status'=>$overall,'id'=>$receiptId]);$open=(int)$this->scalar('SELECT SUM(quantity_bags-received_bags) FROM transfer_shipment_items WHERE shipment_id=?',[$shipmentId]);$this->db->prepare("UPDATE transfer_shipments SET status=:status WHERE id=:id")->execute(['status'=>$open>0?'partially_received':($overall==='rejected'?'return_pending':'received'),'id'=>$shipmentId]);$allOpen=(int)$this->scalar('SELECT SUM(shipped_bags-received_bags) FROM stock_transfer_items WHERE transfer_id=?',[$t['id']]);$new=$allOpen>0?'partially_received':($overall==='accepted'?'accepted':($overall==='rejected'?'return_pending':'partially_accepted'));$this->setStatus($t,$new,'receive',$user);(new DocumentService($this->db))->register('BR',$t['destination_site_id'],'transfer_receipts',$receiptId,'approved',date('Y-m-d H:i:s'),$user);$this->db->commit();return$receiptId;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function dispatchReturn($returnId,array$user){$this->db->beginTransaction();try{$r=$this->row('SELECT * FROM transfer_returns WHERE id=? FOR UPDATE',[$returnId]);if(!$r||$r['status']!=='planned'){throw new RuntimeException('Retour non expédiable.');}$t=$this->lockTransfer($r['transfer_id']);Auth::requireSiteAccess($t['destination_site_id']);$this->db->prepare("UPDATE transfer_returns SET status='dispatched',dispatched_at=NOW() WHERE id=?")->execute([$returnId]);$this->history($t['id'],$t['status'],'return_pending','return_dispatch',$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function receiveReturn($returnId,array$user){$this->db->beginTransaction();try{$r=$this->row('SELECT * FROM transfer_returns WHERE id=? FOR UPDATE',[$returnId]);if(!$r||$r['status']!=='dispatched'){throw new RuntimeException('Retour non réceptionnable ou déjà reçu.');}$t=$this->lockTransfer($r['transfer_id']);Auth::requireSiteAccess($t['source_site_id']);$items=$this->rows('SELECT ri.*,ti.source_finished_stock_id,ti.product_id,ti.bag_format_id FROM transfer_return_items ri JOIN stock_transfer_items ti ON ti.id=ri.transfer_item_id WHERE ri.return_id=? FOR UPDATE',[$returnId]);foreach($items as$i){$stock=$this->lockStock($i['source_finished_stock_id']);$before=$stock['total_weight_kg'];$this->db->prepare("UPDATE finished_stocks SET quantity_bags=quantity_bags+:bags,total_weight_kg=total_weight_kg+:kg,status='active' WHERE id=:id")->execute(['bags'=>$i['quantity_bags'],'kg'=>$i['quantity_kg'],'id'=>$stock['id']]);$this->movement($t,$i,$t['source_site_id'],'return_receipt',$i['quantity_bags'],$i['quantity_kg'],$before,$before+$i['quantity_kg'],0,0,$i['quantity_kg'],0,'return',$returnId,$user);}$this->db->prepare("UPDATE transfer_returns SET status='received',received_at=NOW() WHERE id=?")->execute([$returnId]);$pending=(int)$this->scalar("SELECT COUNT(*) FROM transfer_returns WHERE transfer_id=? AND status<>'received'",[$t['id']]);if(!$pending){$this->setStatus($t,'returned','return_receive',$user);}$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function close($id,array$user){$this->db->beginTransaction();try{$t=$this->lockTransfer($id);$this->expect($t,['accepted','partially_accepted','returned']);$open=(int)$this->scalar('SELECT SUM(shipped_bags-received_bags) FROM stock_transfer_items WHERE transfer_id=?',[$id]);$returns=(int)$this->scalar("SELECT COUNT(*) FROM transfer_returns WHERE transfer_id=? AND status<>'received'",[$id]);if($open>0||$returns>0){throw new RuntimeException('Transfert incomplet.');}foreach($this->lockItems($id)as$item){$releaseBags=(int)$item['reserved_bags']-(int)$item['shipped_bags'];$releaseKg=(float)$item['reserved_kg']-(float)$item['shipped_kg'];if($releaseBags<=0){continue;}$stock=$this->lockStock($item['source_finished_stock_id']);if($stock['reserved_bags']<$releaseBags||$stock['reserved_weight_kg']<$releaseKg){throw new RuntimeException('Réservation incohérente à la clôture.');}$this->db->prepare('UPDATE finished_stocks SET reserved_bags=reserved_bags-:bags,reserved_weight_kg=reserved_weight_kg-:kg WHERE id=:id')->execute(['bags'=>$releaseBags,'kg'=>$releaseKg,'id'=>$stock['id']]);$this->db->prepare("UPDATE stock_transfer_reservations SET status='released',released_at=NOW() WHERE transfer_item_id=:item AND status='active'")->execute(['item'=>$item['id']]);$this->movement($t,$item,$t['source_site_id'],'release',$releaseBags,$releaseKg,$stock['total_weight_kg'],$stock['total_weight_kg'],$stock['reserved_weight_kg'],$stock['reserved_weight_kg']-$releaseKg,0,0,'transfer',$id,$user);}$this->db->prepare("UPDATE stock_transfers SET status='closed',closed_at=NOW() WHERE id=?")->execute([$id]);$this->history($id,$t['status'],'closed','close',$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 private function simple($id,$from,$to,$action,$user){$this->db->beginTransaction();try{$t=$this->lockTransfer($id);$this->expect($t,$from);$this->db->prepare("UPDATE stock_transfers SET status=:status,submitted_at=CASE WHEN :action='submit' THEN NOW() ELSE submitted_at END WHERE id=:id")->execute(['status'=>$to,'action'=>$action,'id'=>$id]);$this->history($id,$t['status'],$to,$action,$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 private function destinationStock($site,$item,$user){$s=$this->db->prepare("SELECT fs.*,bf.weight_kg FROM finished_stocks fs JOIN bag_formats bf ON bf.id=fs.bag_format_id WHERE fs.site_id=:site AND fs.product_id=:product AND fs.bag_format_id=:format AND fs.deleted_at IS NULL ORDER BY fs.packaging_id IS NULL DESC,fs.id LIMIT 1 FOR UPDATE");$s->execute(['site'=>$site,'product'=>$item['product_id'],'format'=>$item['bag_format_id']]);$r=$s->fetch();if($r){return$r;}$this->db->prepare("INSERT INTO finished_stocks(site_id,product_id,bag_format_id,packaging_id,quantity_bags,total_weight_kg,status) VALUES(:site,:product,:format,NULL,0,0,'active')")->execute(['site'=>$site,'product'=>$item['product_id'],'format'=>$item['bag_format_id']]);return$this->lockStock($this->db->lastInsertId());}
 private function nonConformity($t,$receipt,$receiptItem,$expected,$received,$rejected,$user,$description){$ref='NC-'.date('YmdHis').'-'.random_int(100,999);$type=$rejected>0&&$received!=$expected?'quantity_and_quality':($rejected>0?'quality':'quantity');$this->db->prepare('INSERT INTO transfer_non_conformities(transfer_id,receipt_id,receipt_item_id,reference,discrepancy_type,expected_bags,received_bags,rejected_bags,description,created_by) VALUES(:transfer,:receipt,:item,:ref,:type,:expected,:received,:rejected,:description,:user)')->execute(['transfer'=>$t['id'],'receipt'=>$receipt,'item'=>$receiptItem,'ref'=>$ref,'type'=>$type,'expected'=>$expected,'received'=>$received,'rejected'=>$rejected,'description'=>$description,'user'=>$user['id']]);$id=$this->db->lastInsertId();(new DocumentService($this->db))->register('NC',$t['destination_site_id'],'transfer_non_conformities',$id,'approved',date('Y-m-d H:i:s'),$user);}
 private function createReturnLocked($t,$receipt,$item,$bags,$kg,$user){$existing=$this->row("SELECT * FROM transfer_returns WHERE receipt_id=? AND status='planned' FOR UPDATE",[$receipt]);if(!$existing){$number='RET-'.date('YmdHis').'-'.random_int(100,999);$this->db->prepare("INSERT INTO transfer_returns(transfer_id,receipt_id,return_number,planned_at,created_by) VALUES(:transfer,:receipt,:number,NOW(),:user)")->execute(['transfer'=>$t['id'],'receipt'=>$receipt,'number'=>$number,'user'=>$user['id']]);$returnId=$this->db->lastInsertId();(new DocumentService($this->db))->register('BRET',$t['destination_site_id'],'transfer_returns',$returnId,'approved',date('Y-m-d H:i:s'),$user);}else{$returnId=$existing['id'];}$this->db->prepare('INSERT INTO transfer_return_items(return_id,transfer_item_id,quantity_bags,quantity_kg) VALUES(:return,:item,:bags,:kg)')->execute(['return'=>$returnId,'item'=>$item['id'],'bags'=>$bags,'kg'=>$kg]);}
 private function movement($t,$i,$site,$type,$bags,$kg,$pb,$pa,$rb,$ra,$tb,$ta,$sourceType,$sourceId,$user){$this->db->prepare('INSERT INTO stock_transfer_movements(transfer_id,transfer_item_id,site_id,movement_type,quantity_bags,quantity_kg,physical_before_kg,physical_after_kg,reserved_before_kg,reserved_after_kg,transit_before_kg,transit_after_kg,source_type,source_id,created_by) VALUES(:transfer,:item,:site,:type,:bags,:kg,:pb,:pa,:rb,:ra,:tb,:ta,:source_type,:source_id,:user)')->execute(['transfer'=>$t['id'],'item'=>$i['id'],'site'=>$site,'type'=>$type,'bags'=>$bags,'kg'=>$kg,'pb'=>$pb,'pa'=>$pa,'rb'=>$rb,'ra'=>$ra,'tb'=>max($tb,0),'ta'=>max($ta,0),'source_type'=>$sourceType,'source_id'=>$sourceId,'user'=>$user['id']]);}
 private function setStatus($t,$new,$action,$user){$this->db->prepare('UPDATE stock_transfers SET status=:status WHERE id=:id')->execute(['status'=>$new,'id'=>$t['id']]);$this->history($t['id'],$t['status'],$new,$action,$user);}private function history($id,$old,$new,$action,$user,$reason=null){$this->db->prepare('INSERT INTO stock_transfer_history(transfer_id,old_status,new_status,action,actor_id,reason) VALUES(:id,:old,:new,:action,:user,:reason)')->execute(['id'=>$id,'old'=>$old,'new'=>$new,'action'=>$action,'user'=>$user['id'],'reason'=>$reason]);}
 private function expect($t,$states){if(!$t||!in_array($t['status'],$states,true)){throw new RuntimeException('Statut de transfert incompatible.');}}private function lockTransfer($id){return$this->row('SELECT * FROM stock_transfers WHERE id=? AND deleted_at IS NULL FOR UPDATE',[$id]);}private function lockItems($id){return$this->rows('SELECT * FROM stock_transfer_items WHERE transfer_id=? ORDER BY id FOR UPDATE',[$id]);}private function shipmentItems($id){return$this->rows('SELECT * FROM transfer_shipment_items WHERE shipment_id=? ORDER BY id FOR UPDATE',[$id]);}
 private function lockStock($id){return$this->row('SELECT fs.*,bf.weight_kg FROM finished_stocks fs JOIN bag_formats bf ON bf.id=fs.bag_format_id WHERE fs.id=? AND fs.deleted_at IS NULL FOR UPDATE',[$id]);}private function row($sql,$p=[]){$s=$this->db->prepare($sql);$s->execute($p);return$s->fetch();}private function rows($sql,$p=[]){$s=$this->db->prepare($sql);$s->execute($p);return$s->fetchAll();}private function scalar($sql,$p=[]){$s=$this->db->prepare($sql);$s->execute($p);return$s->fetchColumn();}
}
